// Store one homelab event for the 08:00 digest. POST /webhook/homelab-event/<diun|kuma|backup|scrutiny>
const sd = $getWorkflowStaticData('global');
sd.events = sd.events || [];
const q = $json.query || {};
const b = $json.body || {};
const source = ($json.params && $json.params.source) || q.source || 'other';
let line;
if (source === 'diun') {
  line = `Image update: ${b.image || ''} (${b.status || 'new'}) on ${b.hostname || 'unknown host'}`;
} else if (source === 'kuma') {
  const st = b.heartbeat ? (b.heartbeat.status === 0 ? 'DOWN' : b.heartbeat.status === 1 ? 'UP' : '') : '';
  line = `${(b.monitor && b.monitor.name) || 'monitor'} ${st}: ${b.msg || ''}`.trim();
} else {
  line = b.message || b.title || JSON.stringify(b).slice(0, 300);
}
sd.events.push({ t: new Date().toISOString(), source, line });
if (sd.events.length > 500) sd.events = sd.events.slice(-500);
return [{ json: { stored: true } }];

// Daily digest: everything collected since yesterday, then clear.
const sd = $getWorkflowStaticData('global');
const ev = sd.events || [];
sd.events = [];
const day = new Date().toLocaleDateString('en-US', { timeZone: 'America/Los_Angeles', dateStyle: 'medium' });
if (ev.length === 0) {
  return [{ json: { subject: `Homelab digest ${day}: nothing to report`, text: 'No app outages, image updates, disk warnings or backup failures in the last 24 hours.' } }];
}
const names = { kuma: 'App status (non-critical)', diun: 'Image updates available', scrutiny: 'Disk health', backup: 'Backups', other: 'Other' };
const groups = {};
for (const e of ev) (groups[e.source] = groups[e.source] || []).push(e);
let text = '';
for (const [src, items] of Object.entries(groups)) {
  text += `${names[src] || src} (${items.length})\n`;
  for (const e of items) {
    const t = new Date(e.t).toLocaleString('en-US', { timeZone: 'America/Los_Angeles', hour: '2-digit', minute: '2-digit', month: 'short', day: 'numeric' });
    text += `  - ${t}  ${e.line}\n`;
  }
  text += '\n';
}
return [{ json: { subject: `Homelab digest ${day}: ${ev.length} item(s)`, text } }];
